svg.script:
var V = (typeof visb_vars !== "undefined") ? visb_vars : (window.visb_vars = {});
if (V["SEL"] === undefined) V["SEL"] = "0";
if (V["TARGET"] === undefined) V["TARGET"] = "NONE";

var selHand = null;
var selSlot = null;

var ALL_SLOTS = [
  "ACTIVE_P1", "BENCH1_P1", "BENCH2_P1", "BENCH3_P1",
  "ACTIVE_P2", "BENCH1_P2", "BENCH2_P2", "BENCH3_P2"
];

var BASICS = {
  CHARMANDER: true, SQUIRTLE: true, BULBASAUR: true,
  PIKACHU: true, SNORLAX: true, EEVEE: true
};

var PRE_EVOLUTION = {
  CHARMELEON: "CHARMANDER",
  CHARIZARD: "CHARMELEON",
  WARTORTLE: "SQUIRTLE",
  BLASTOISE: "WARTORTLE",
  IVYSAUR: "BULBASAUR",
  VENUSAUR: "IVYSAUR",
  RAICHU: "PIKACHU",
  VAPOREON: "EEVEE",
  FLAREON: "EEVEE",
  JOLTEON: "EEVEE"
};

function getText(id) {
  var e = document.getElementById(id);
  return e ? (e.textContent || "").trim() : "";
}

function paint(id, color, w, dash) {
  var e = document.getElementById(id);
  if (!e) return;
  e.setAttribute("stroke", color);
  e.setAttribute("stroke-width", w);
  if (dash) {
    e.setAttribute("stroke-dasharray", dash);
  } else {
    e.removeAttribute("stroke-dasharray");
  }
}

function clearHandHighlight() {
  if (selHand) {
    var prevIdx = parseInt(selHand.split("_")[2], 10);
    paint(selHand, prevIdx >= 8 ? "#6b7280" : "none", prevIdx >= 8 ? "1" : "0", null);
    selHand = null;
  }
}

function clearSlotHighlights() {
  for (var i = 0; i < ALL_SLOTS.length; i++) {
    var s = ALL_SLOTS[i];
    paint("slot_" + s, "none", "0", null);
  }
  selSlot = null;
}

function restoreTargetHighlight() {
  if (V["TARGET"] && V["TARGET"] !== "NONE") {
    selSlot = "slot_" + V["TARGET"];
    paint(selSlot, "#2563eb", "3", null);
  }
}

function highlightValidSlotsForCard(cardName, player) {
  clearSlotHighlights();
  var phase = getText("txt_phase");
  var turn = getText("txt_turn") || player;

  if (phase === "PLACING_ACTIVE") {
    var actSlot = "ACTIVE_" + player;
    paint("slot_" + actSlot, "#16a34a", "3", "6,3");
    return;
  }

  if (player !== turn) {
    restoreTargetHighlight();
    return;
  }

  var playerSlots = ["ACTIVE_" + turn, "BENCH1_" + turn, "BENCH2_" + turn, "BENCH3_" + turn];
  var benchSlots = ["BENCH1_" + turn, "BENCH2_" + turn, "BENCH3_" + turn];

  if (cardName === "PROF_RESEARCH" || cardName === "PROFESSOR_RESEARCH") {
    paint("slot_ACTIVE_" + turn, "#16a34a", "3.5", "6,3");
  } else if (cardName.indexOf("_ENERGY") !== -1) {
    for (var i = 0; i < playerSlots.length; i++) {
      if (getText("poke_" + playerSlots[i]) !== "Vazio") {
        paint("slot_" + playerSlots[i], "#16a34a", "3", "6,3");
      }
    }
  } else if (cardName === "POTION") {
    for (var j = 0; j < playerSlots.length; j++) {
      if (getText("poke_" + playerSlots[j]) !== "Vazio") {
        paint("slot_" + playerSlots[j], "#16a34a", "3", "6,3");
      }
    }
  } else if (BASICS[cardName]) {
    for (var k = 0; k < benchSlots.length; k++) {
      if (getText("poke_" + benchSlots[k]) === "Vazio") {
        paint("slot_" + benchSlots[k], "#16a34a", "3", "6,3");
      }
    }
  } else if (PRE_EVOLUTION[cardName]) {
    var needed = PRE_EVOLUTION[cardName];
    for (var m = 0; m < playerSlots.length; m++) {
      var sl = playerSlots[m];
      var borderEl = document.getElementById("new_border_" + sl);
      var isNew = borderEl && borderEl.getAttribute("visibility") === "visible";
      if (getText("poke_" + sl) === needed && !isNew) {
        paint("slot_" + sl, "#16a34a", "3", "6,3");
      }
    }
  } else {
    restoreTargetHighlight();
  }
}

function clearSelection() {
  V["SEL"] = "0";
  V["TARGET"] = "NONE";
  clearHandHighlight();
  clearSlotHighlights();
}

function onHand(ev) {
  var m = /^hand_(P[12])_(\d+)$/.exec(ev.target.id || "");
  if (!m) return;
  var player = m[1];
  var idx = m[2];
  var cardName = getText("hand_text_" + player + "_" + idx);
  if (!cardName || cardName === "-") return;

  var clickedId = "hand_" + player + "_" + idx;
  if (selHand === clickedId) {
    V["SEL"] = "0";
    clearHandHighlight();
    clearSlotHighlights();
    restoreTargetHighlight();
    return;
  }

  clearHandHighlight();
  V["SEL"] = idx;
  selHand = clickedId;
  paint(selHand, "#2563eb", "3", null);
  highlightValidSlotsForCard(cardName, player);
}

function onSlot(name) {
  clearSlotHighlights();
  V["TARGET"] = name;
  selSlot = "slot_" + name;
  paint(selSlot, "#2563eb", "3", null);

  setTimeout(function () {
    V["SEL"] = "0";
    clearHandHighlight();
  }, 150);
}

function onActionConsumeTarget() {
  setTimeout(function () {
    V["TARGET"] = "NONE";
    clearSlotHighlights();
  }, 150);
}

function onActionClear() {
  setTimeout(function () {
    clearSelection();
  }, 150);
}

function simplifyEnergyLabel(el) {
  if (!el) return;
  var txt = el.textContent || "";
  var m = /^Energias:\s*\d+\s*tipo\s*\/\s*(\d+)\s*tot$/.exec(txt.trim());
  if (m) {
    el.textContent = "Energias: " + m[1];
  }
}

(function initEnergyObservers() {
  for (var i = 0; i < ALL_SLOTS.length; i++) {
    (function (el) {
      if (!el) return;
      simplifyEnergyLabel(el);
      if (typeof MutationObserver !== "undefined") {
        var obs = new MutationObserver(function () {
          simplifyEnergyLabel(el);
        });
        obs.observe(el, { childList: true, characterData: true, subtree: true });
      }
    })(document.getElementById("energy_" + ALL_SLOTS[i]));
  }
})();
